const MC = require('./matchcore.js'), P = require('./puzzles.src.js'), fs = require('fs');
function* comb(arr, k, start = 0, acc = []) { if (acc.length === k) { yield acc; return; } for (let i = start; i <= arr.length - (k - acc.length); i++) { acc.push(arr[i]); yield* comb(arr, k, i + 1, acc); acc.pop(); } }
function ok(p, set) { return p.kind === 'eq' ? MC.eqTrue(p, set) : MC.judge(p, set).ok; }
function solutions(p, n, limit = Infinity) {
  const start = p.kind === 'eq' ? MC.eqStart(p) : new Set(MC.fromCells(p.cells));
  const slots = p.kind === 'eq' ? MC.eqSlots(p) : MC.slotsFor(p.W, p.H);
  const present = slots.filter(s => start.has(s)), empty = slots.filter(s => !start.has(s));
  const out = [];
  if (p.kind === 'remove') { for (const r of comb(present, n)) { const s = new Set(start); r.forEach(e => s.delete(e)); if (ok(p, s)) { out.push({ remove: [...r] }); if (out.length >= limit) break; } } }
  else for (const r of comb(present, n)) { for (const a of comb(empty, n)) { const s = new Set(start); r.forEach(e => s.delete(e)); a.forEach(e => s.add(e)); if (ok(p, s)) { out.push({ from: [...r], to: [...a] }); if (out.length >= limit) break; } } if (out.length >= limit) break; }
  return out;
}
const gen = []; let bad = 0;
for (const p0 of P) {
  const p = { ...p0 }; if (p.kind === 'eq') p.glyphs = MC.glyphsFor(p.eq);
  const start = p.kind === 'eq' ? MC.eqStart(p) : new Set(MC.fromCells(p.cells));
  if (ok(p, start)) { console.log('FAIL', p.id, 'already solved at start'); bad++; continue; }
  let fewer = 0; for (let k = 1; k < p.n; k++) fewer += solutions(p, k, 1).length;
  const sols = solutions(p, p.n);
  const line = `${p.id} ${p.kind} n=${p.n}: ${sols.length} answer(s)` + (fewer ? `, BUT ${fewer} with fewer moves` : '');
  if (!sols.length || (fewer && p.kind !== 'remove')) { console.log('FAIL', line); bad++; continue; }
  console.log('ok  ', line);
  const out = { ...p0, sol: sols[0], answers: sols.length }; delete out.glyphs;
  if (p.kind !== 'eq') out.sticks = MC.fromCells(p.cells), delete out.cells;
  gen.push(out);
}
if (bad) { console.log(bad, 'puzzle(s) failed'); process.exit(1); }
fs.writeFileSync('puzzles.gen.js', '// Generated by verify.js from puzzles.src.js. Do not edit.\nconst PUZZLES = ' + JSON.stringify(gen) + ';\n');
console.log('wrote', gen.length, 'puzzles');
